boolean isBitSet(int n, int k) {
    return ((n >> k) & 1) == 1;
}

int setBit(int n, int k) {
    return n | (1 << k);
}

int clearBit(int n, int k) {
    return n & ~(1 << k);
}

int toggleBit(int n, int k) {
    return n ^ (1 << k);
}

int countSetBits(int n) {
    int count = 0;

    while (n != 0) {
        n = n & (n - 1);
        count++;
    }

    return count;
}

int singleNumber(int[] arr) {
    int result = 0;

    for (int x : arr) {
        result ^= x;
    }

    return result;
}

